    // ---- v1/v2 CBPY (round 75 — binary cross-check) ----

    #[test]
    fn cbpy_v1_v2_alphabet_is_sixteen_entries() {
        // Per H.263 §5.3.5 / MPEG-4 Part 2 Table B-6 the CBPY alphabet
        // has exactly 16 symbols (4-bit luma-CBP patterns 0..=15). The
        // build-time extractor filters out the 2 reserved-sentinel
        // symbols (0x10, 0x11) the binary places at LUT slots 0..1.
        assert_eq!(CBPY_V1_V2_RAW.len(), 16);
        let syms: Vec<u8> = CBPY_V1_V2_RAW.iter().map(|&(s, _, _)| s).collect();
        assert_eq!(
            syms,
            (0..=15u8).collect::<Vec<_>>(),
            "expected contiguous CBPY symbols 0..=15"
        );
    }

    #[test]
    fn cbpy_v1_v2_max_bit_length_is_six() {
        // Per spec/07 §1.3 the helper is invoked with max-bitlen 6.
        for &(_, bl, _) in CBPY_V1_V2_RAW {
            assert!((1..=6).contains(&bl), "CBPY bl={bl} out of [1,6]");
        }
    }

    #[test]
    fn cbpy_v1_v2_matches_hand_derived_table() {
        // The build cross-check already panics on mismatch, but pin the
        // invariant here too so a regression surfaces as a test failure
        // (not just a build failure) for downstream consumers.
        use crate::tables::CBPY_INTRA_TABLE;
        for &(sym, bl, code) in CBPY_V1_V2_RAW {
            let hand = CBPY_INTRA_TABLE
                .iter()
                .find(|e| e.value == sym)
                .unwrap_or_else(|| panic!("hand table missing sym {sym}"));
            assert_eq!(
                hand.bits, bl,
                "sym {sym}: hand-derived bl {} vs binary bl {bl}",
                hand.bits
            );
            assert_eq!(
                hand.code, code,
                "sym {sym}: hand-derived code 0b{:b} vs binary code 0b{:b}",
                hand.code, code
            );
        }
    }

    #[test]
    fn cbpy_v1_v2_kraft_sum_accounts_for_reserved_sentinels() {
        // Kraft sum over the 16 alphabet entries = 1 - 2*2^-6 = 31/32,
        // with the 2 leaves reserved for the (sym=0x10, sym=0x11)
        // reserved sentinels at bl=6. In 32-bit fixed-point arithmetic:
        // target = 2^32 - 2 * 2^(32-6).
        let kraft: u64 = CBPY_V1_V2_RAW
            .iter()
            .map(|&(_, bl, _)| 1u64 << (32 - bl as u32))
            .sum();
        let target: u64 = (1u64 << 32) - 2 * (1u64 << (32 - 6));
        assert_eq!(kraft, target);
    }

    #[test]
    fn cbpy_v1_v2_sentinels_are_two_at_bl_six() {
        // Per spec/07 §1.3 the binary fills the two unused 6-bit prefix
        // slots `000000` and `000001` with reserved-sentinel symbols
        // (0x10, 0x11). Both must be at bl=6 (otherwise they would
        // shadow real codewords).
        assert_eq!(CBPY_V1_V2_SENTINELS.len(), 2);
        for &(sym, bl, _) in CBPY_V1_V2_SENTINELS {
            assert!(sym >= 16, "sentinel sym {sym} inside CBPY alphabet");
            assert_eq!(bl, 6, "sentinel sym {sym} bl {bl} != 6");
        }
        // The two sentinels occupy code positions 0 and 1 of a 6-bit
        // window: `000000` and `000001`. Sort by code to compare.
        let mut codes: Vec<u32> = CBPY_V1_V2_SENTINELS.iter().map(|&(_, _, c)| c).collect();
        codes.sort_unstable();
        assert_eq!(codes, vec![0, 1]);
    }

    #[test]
    fn cbpy_v1_v2_is_prefix_free() {
        // Standard prefix-freedom check, mirrors mcbpc_v1_is_prefix_free.
        for (i, &(_, bla, ca)) in CBPY_V1_V2_RAW.iter().enumerate() {
            for (j, &(_, blb, cb)) in CBPY_V1_V2_RAW.iter().enumerate() {
                if i == j || bla == blb {
                    continue;
                }
                let (short_bl, short_c, long_bl, long_c) = if bla < blb {
                    (bla, ca, blb, cb)
                } else {
                    (blb, cb, bla, ca)
                };
                let shift = long_bl - short_bl;
                let long_prefix = long_c >> shift;
                assert_ne!(
                    long_prefix, short_c,
                    "CBPY: code 0x{short_c:x} (bl {short_bl}) is a prefix of 0x{long_c:x} (bl {long_bl})"
                );
            }
        }
    }

    #[test]
    fn cbpy_v1_v2_short_code_is_pattern_fifteen() {
        // Per H.263 Table 8 the 2-bit code `11` decodes to CBPY pattern
        // 15 (all four luma blocks coded) — the most frequent intra
        // pattern. Binary cross-check pins this load-bearing value.
        let (sym_15_bl, sym_15_code) = CBPY_V1_V2_RAW
            .iter()
            .find_map(|&(s, bl, c)| (s == 15).then_some((bl, c)))
            .unwrap();
        assert_eq!(sym_15_bl, 2);
        assert_eq!(sym_15_code, 0b11);
    }

